const MD_ropeXS=(cx,cy,R,core)=>{const rs=R/3;let s=`<circle cx="${cx}" cy="${cy}" r="${R+3}" fill="none" stroke="${MD_LIGHT}" stroke-width="3"/>`;
 if(core==='fibre')s+=`<circle cx="${cx}" cy="${cy}" r="${rs*.98}" fill="${MD_HEMP}" stroke="${ORG}" stroke-width="3"/>`;
 else{const q=rs/3;for(let i=0;i<6;i++){const a=i*Math.PI/3;s+=`<circle cx="${(cx+2*q*Math.cos(a)).toFixed(1)}" cy="${(cy+2*q*Math.sin(a)).toFixed(1)}" r="${q*.95}" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="1.5"/>`}s+=`<circle cx="${cx}" cy="${cy}" r="${q*.95}" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="1.5"/>`}
 for(let i=0;i<6;i++){const a=i*Math.PI/3+Math.PI/6;s+=MD_strand(cx+2*rs*Math.cos(a),cy+2*rs*Math.sin(a),rs*.98,'#E7F5FF',BLU)}
 return s};
/* a rope seen from the side, laid along x from 0 to len, height h: strands lean one way;
   regular lay: the wires lean the other way; lang lay: the wires lean with the strands */
const MD_ropeSide=(id,len,h,lang)=>{const dx=h*.9,sw=34;let st='',wi='';
 for(let x=-dx-sw,i=0;x<len+sw;x+=sw,i++){st+=`<polygon points="${x},${h} ${x+sw},${h} ${x+sw+dx},0 ${x+dx},0" fill="${i%2?'#D0E4F5':'#E7F5FF'}" stroke="${BLU}" stroke-width="2"/>`;
  for(let k=1;k<4;k++){const f=k/4,yb=h*(1-f)+4,yt=h*(1-f)-4;
   if(lang){const x0=x+sw*.25+dx*f;wi+=MD_L(x0,h*(1-f)+7,x0+dx*.2,h*(1-f)-7+0.1,MD_STEEL,3)}
   else{const xm=x+sw*.5+dx*f;wi+=MD_L(xm-10,h*(1-f)-6,xm+10,h*(1-f)+6,MD_STEEL,3)}}}
 return `<clipPath id="${id}"><rect x="0" y="0" width="${len}" height="${h}" rx="${h/2}"/></clipPath><g clip-path="url(#${id})">${st}${wi}</g><rect x="0" y="0" width="${len}" height="${h}" rx="${h/2}" fill="none" stroke="${MD_DARK}" stroke-width="3"/>`};
/* the load budget of the goods-hoist rope, in kN, drawn to scale over w px */
const MD_budget=(x,y,w,h,mode)=>{const k=w/67.76;let s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="#FFFFFF" stroke="${MD_DARK}" stroke-width="3"/>`;
 if(mode==='static'){for(let i=0;i<7;i++){const bw=Math.min(9.81*k,w-i*9.81*k);s+=`<rect x="${(x+i*9.81*k).toFixed(1)}" y="${y+6}" width="${(bw-3).toFixed(1)}" height="${h-12}" rx="3" fill="${TRED}" fill-opacity="${i<6?.55:.25}"/>`}}
 else{const fb=5.679*k;s+=`<rect x="${(x+w-fb).toFixed(1)}" y="${y+3}" width="${(fb-3).toFixed(1)}" height="${h-6}" rx="3" fill="${GRN}" fill-opacity=".85"/>`;
  for(let i=0;i<6;i++){const bw=Math.min(10.956*k,(67.76-5.679)*k-i*10.956*k);s+=`<rect x="${(x+i*10.956*k).toFixed(1)}" y="${y+6}" width="${(bw-3).toFixed(1)}" height="${h-12}" rx="3" fill="${ORG}" fill-opacity="${i<5?.6:.3}"/>`}}
 return s};

